begin;
create or replace function public.register_notification_device(p_token text, p_platform text, p_app_variant text) returns public.notification_devices language plpgsql security definer set search_path='public','pg_temp' as $$ declare r public.notification_devices; begin if auth.uid() is null then raise exception 'Oturum gerekli'; end if; if length(trim(coalesce(p_token,''))) < 20 then raise exception 'Geçersiz bildirim tokenı'; end if; if p_platform not in ('android','web') then raise exception 'Geçersiz platform'; end if; if p_app_variant not in ('admin','staff') then raise exception 'Geçersiz uygulama'; end if; if not exists (select 1 from public.org_memberships m join public.org_roles r on r.id=m.role_id and r.active=true where m.user_id=auth.uid() and m.active=true and (p_app_variant='staff' or coalesce(r.is_admin_role,false)=true)) then raise exception 'Uygulama yetkisi gerekli'; end if; insert into public.notification_devices(user_id,token,platform,app_variant,active,last_seen_at,updated_at) values(auth.uid(),trim(p_token),p_platform,p_app_variant,true,now(),now()) on conflict (user_id,token,app_variant) do update set platform=excluded.platform,active=true,last_seen_at=now(),updated_at=now() returning * into r; return r; end; $$;
revoke all on function public.register_notification_device(text,text,text) from public,anon; grant execute on function public.register_notification_device(text,text,text) to authenticated;
drop trigger if exists trg_quote_new_notification on public.teklifler; drop trigger if exists trg_quote_after_notify on public.teklifler; drop trigger if exists trg_offer_change_notification on public.teklifler; drop trigger if exists trg_business_change_offer on public.teklifler; drop trigger if exists trg_job_change_notification on public.jobs; drop trigger if exists trg_business_change_jobs on public.jobs; drop trigger if exists trg_notify_business_change_equipment on public.equipment; drop trigger if exists trg_business_notification_offer on public.teklifler; drop trigger if exists trg_business_notification_job on public.jobs; drop trigger if exists trg_business_notification_equipment on public.equipment;
create trigger trg_business_notification_offer after insert or update on public.teklifler for each row execute function public.dispatch_business_notification();
create trigger trg_business_notification_job after update on public.jobs for each row execute function public.dispatch_business_notification();
create trigger trg_business_notification_equipment after update on public.equipment for each row execute function public.dispatch_business_notification();
commit;
